package com.therobbots.player;
import android.app.*;import android.os.*;import android.content.*;import android.database.Cursor;import android.graphics.Color;import android.graphics.Typeface;import android.graphics.Bitmap;import android.graphics.BitmapFactory;import android.graphics.drawable.GradientDrawable;import android.media.MediaPlayer;import android.net.Uri;import android.provider.DocumentsContract;import android.text.*;import android.view.*;import android.widget.*;import java.util.*;
public class MainActivity extends Activity {
final int BG=Color.rgb(7,9,13), GOLD=Color.rgb(240,192,94),RED=Color.rgb(196,32,45), PANEL=Color.rgb(20,23,30); LinearLayout root,list,footer;EditText search;MediaPlayer player;Uri folder;ArrayList<Song> songs=new ArrayList<>(),queue=new ArrayList<>();int current=-1;int shuffleMode=0;ArrayList<String> albumOrder=new ArrayList<>();HashMap<String,Uri> covers=new HashMap<>();
static class Song {Uri uri;String title,album;Song(Uri u,String t,String a){uri=u;title=t;album=a;}}
public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);getWindow().setNavigationBarColor(BG);String saved=getPreferences(0).getString("folder",null);if(saved!=null){folder=Uri.parse(saved);scan();}draw();}
TextView text(String s,int size,int color){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);t.setPadding(12,14,12,14);return t;}
GradientDrawable bg(int color){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(30);d.setStroke(2,Color.rgb(100,38,43));return d;}
int dp(int v){return (int)(v*getResources().getDisplayMetrics().density+0.5f);}
GradientDrawable metallic(boolean primary){GradientDrawable d=new GradientDrawable(GradientDrawable.Orientation.TL_BR,primary?new int[]{Color.rgb(255,210,111),Color.rgb(145,22,34),Color.rgb(57,8,19)}:new int[]{Color.rgb(90,29,38),Color.rgb(29,31,39),Color.rgb(13,16,24)});d.setCornerRadius(dp(18));d.setStroke(dp(1),primary?GOLD:Color.rgb(130,69,61));return d;}
void draw(){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(12),dp(8),dp(12),dp(10));root.setBackgroundColor(BG);setContentView(root);TextView title=text("THE ROBBOTS",28,GOLD);title.setTypeface(null,1);root.addView(title);root.addView(text("BY ROD PEN    /    IRON EDITION",11,RED));Button select=new Button(this);select.setText(folder==null?"Seleccionar carpeta The Robbots":"Cambiar carpeta / Actualizar");select.setTextColor(GOLD);select.setBackground(bg(PANEL));root.addView(select);select.setOnClickListener(v->{if(folder==null)choose();else{scan();draw();}});root.addView(text(songs.size()+" canciones en tu biblioteca",14,GOLD));search=new EditText(this);search.setSingleLine(true);search.setTextColor(-1);search.setHintTextColor(GOLD);search.setHint("⌕  Buscar álbum o canción");search.setTextSize(15);search.setPadding(20,14,20,14);search.setBackground(bg(PANEL));root.addView(search);ScrollView scroll=new ScrollView(this);list=new LinearLayout(this);list.setOrientation(1);scroll.addView(list);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));footer=new LinearLayout(this);footer.setOrientation(1);footer.setPadding(dp(8),dp(5),dp(8),dp(8));footer.setBackground(metallic(false));LinearLayout.LayoutParams fp=new LinearLayout.LayoutParams(-1,-2);fp.setMargins(0,dp(6),0,dp(4));root.addView(footer,fp);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){albums(s.toString());}public void afterTextChanged(Editable e){}});albums("");controls();}
void choose(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT_TREE);i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_GRANT_PERSISTABLE_URI_PERMISSION);startActivityForResult(i,42);}
protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==42&&c==RESULT_OK&&d!=null){folder=d.getData();getContentResolver().takePersistableUriPermission(folder,Intent.FLAG_GRANT_READ_URI_PERMISSION);getPreferences(0).edit().putString("folder",folder.toString()).apply();scan();draw();}}
void scan(){songs.clear();covers.clear();if(folder==null)return;try{walk(DocumentsContract.getTreeDocumentId(folder),"",0);}catch(Exception e){Toast.makeText(this,"Error leyendo carpeta",1).show();}Collections.sort(songs,(a,b)->(a.album+a.title).compareToIgnoreCase(b.album+b.title));syncAlbumOrder();}
void walk(String id,String album,int depth){if(depth>7)return;Uri children=DocumentsContract.buildChildDocumentsUriUsingTree(folder,id);try(Cursor c=getContentResolver().query(children,new String[]{DocumentsContract.Document.COLUMN_DOCUMENT_ID,DocumentsContract.Document.COLUMN_DISPLAY_NAME,DocumentsContract.Document.COLUMN_MIME_TYPE},null,null,null)){if(c==null)return;while(c.moveToNext()){String child=c.getString(0),name=c.getString(1),mime=c.getString(2);if(DocumentsContract.Document.MIME_TYPE_DIR.equals(mime))walk(child,depth==0?name:album,depth+1);else if(name.toLowerCase(Locale.ROOT).matches("(cover|folder|front|albumart|tapa|portada)\\.(jpg|jpeg|png|webp)")){String key=album.isEmpty()?"The Robbots":album;covers.put(key,DocumentsContract.buildDocumentUriUsingTree(folder,child));}else if(name.toLowerCase(Locale.ROOT).matches(".*\\.(mp3|m4a|wav|flac|ogg)"))songs.add(new Song(DocumentsContract.buildDocumentUriUsingTree(folder,child),name.replaceFirst("(?i)\\.(mp3|m4a|wav|flac|ogg)$",""),album.isEmpty()?"The Robbots":album));}}catch(Exception ignored){}}
void syncAlbumOrder(){String saved=getPreferences(0).getString("album_order","");albumOrder.clear();if(!saved.isEmpty())for(String name:saved.split("\n"))if(!name.isEmpty()&&!albumOrder.contains(name))albumOrder.add(name);for(Song s:songs)if(!albumOrder.contains(s.album))albumOrder.add(s.album);saveAlbumOrder();}
void saveAlbumOrder(){getPreferences(0).edit().putString("album_order",android.text.TextUtils.join("\n",albumOrder)).apply();}
void moveAlbum(String name,int delta){int i=albumOrder.indexOf(name),j=i+delta;if(i<0||j<0||j>=albumOrder.size())return;Collections.swap(albumOrder,i,j);saveAlbumOrder();albums(search.getText().toString());}
void albumMenu(String name){new AlertDialog.Builder(this).setTitle(name).setItems(new String[]{"Subir disco","Bajar disco"},(d,which)->moveAlbum(name,which==0?-1:1)).show();}
void playNextAlbum(){if(queue.isEmpty()||current<0){next(1);return;}String name=queue.get(current).album;int idx=albumOrder.indexOf(name);if(idx<0||albumOrder.isEmpty()){next(1);return;}for(int offset=1;offset<=albumOrder.size();offset++){String nextAlbum=albumOrder.get((idx+offset)%albumOrder.size());ArrayList<Song> tracks=new ArrayList<>();for(Song s:songs)if(s.album.equals(nextAlbum))tracks.add(s);if(!tracks.isEmpty()){queue=tracks;play(0);return;}}}
void advance(){if(queue.isEmpty())return;if(shuffleMode==2){queue=new ArrayList<>(songs);play(new Random().nextInt(queue.size()));return;}if(shuffleMode==1){play(new Random().nextInt(queue.size()));return;}if(current+1<queue.size())play(current+1);else if(queue.size()==songs.size())play(0);else playNextAlbum();}
ImageView coverView(String album,int size){ImageView img=new ImageView(this);img.setScaleType(ImageView.ScaleType.CENTER_CROP);img.setBackground(metallic(false));Uri u=covers.get(album);if(u!=null){try(java.io.InputStream stream=getContentResolver().openInputStream(u)){BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeStream(stream,null,o);int sample=1;while(o.outWidth/sample>size*3||o.outHeight/sample>size*3)sample*=2;try(java.io.InputStream stream2=getContentResolver().openInputStream(u)){BitmapFactory.Options scaled=new BitmapFactory.Options();scaled.inSampleSize=sample;Bitmap bmp=BitmapFactory.decodeStream(stream2,null,scaled);if(bmp!=null)img.setImageBitmap(bmp);}}catch(Exception ignored){}}else{img.setImageResource(com.therobbots.player.R.drawable.ic_iron);}return img;}
void albums(String filter){list.removeAllViews();LinkedHashMap<String,ArrayList<Song>> groups=new LinkedHashMap<>();for(Song s:songs)if(s.title.toLowerCase(Locale.ROOT).contains(filter.toLowerCase(Locale.ROOT))||s.album.toLowerCase(Locale.ROOT).contains(filter.toLowerCase(Locale.ROOT)))groups.computeIfAbsent(s.album,k->new ArrayList<>()).add(s);for(String name:albumOrder)if(groups.containsKey(name)){ArrayList<Song> tracks=groups.get(name);LinearLayout row=new LinearLayout(this);row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(dp(7),dp(6),dp(7),dp(6));row.setBackground(bg(PANEL));ImageView cover=coverView(name,72);row.addView(cover,new LinearLayout.LayoutParams(dp(72),dp(72)));TextView t=text(name+"\n"+tracks.size()+" temas",16,GOLD);t.setMaxLines(3);t.setEllipsize(android.text.TextUtils.TruncateAt.END);LinearLayout.LayoutParams tp=new LinearLayout.LayoutParams(0,-2,1);tp.setMargins(dp(12),0,0,0);row.addView(t,tp);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(5),0,dp(5));list.addView(row,p);row.setOnClickListener(v->tracks(tracks));row.setOnLongClickListener(v->{albumMenu(name);return true;});}if(songs.isEmpty())list.addView(text("Seleccioná tu carpeta The Robbots.",17,GOLD));}
void tracks(ArrayList<Song> tracks){list.removeAllViews();TextView back=text("‹  Volver a discos",19,GOLD);list.addView(back);back.setOnClickListener(v->albums(search.getText().toString()));for(int i=0;i<tracks.size();i++){final int index=i;TextView t=text((i+1)+".   "+tracks.get(i).title,15,-1);list.addView(t);t.setOnClickListener(v->{queue=new ArrayList<>(tracks);play(index);});}}
void controls(){footer.removeAllViews();TextView now=text(current>=0&&current<queue.size()?queue.get(current).title:"THE ROBBOTS  •  MI MÚSICA",15,GOLD);now.setGravity(Gravity.CENTER);now.setSingleLine(true);now.setEllipsize(android.text.TextUtils.TruncateAt.END);now.setPadding(dp(4),dp(4),dp(4),dp(2));footer.addView(now);TextView subtitle=text(current>=0&&current<queue.size()?queue.get(current).album:"IRON EDITION",11,Color.rgb(173,168,163));subtitle.setGravity(Gravity.CENTER);subtitle.setPadding(dp(3),0,dp(3),dp(4));footer.addView(subtitle);if(current>=0&&current<queue.size()){ImageView art=coverView(queue.get(current).album,96);LinearLayout.LayoutParams ap=new LinearLayout.LayoutParams(dp(66),dp(66));ap.gravity=Gravity.CENTER_HORIZONTAL;ap.bottomMargin=dp(4);footer.addView(art,ap);}LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER);bar.setMinimumHeight(dp(62));footer.addView(bar);button(bar,shuffleMode==0?"ORD":shuffleMode==1?"ÁLB":"TODO",()->{shuffleMode=(shuffleMode+1)%3;Toast.makeText(this,shuffleMode==0?"Orden normal":shuffleMode==1?"Aleatorio en el álbum":"Aleatorio en toda la biblioteca",Toast.LENGTH_SHORT).show();controls();});button(bar,"❮❮",()->next(-1));reactor(bar);button(bar,"❯❯",()->next(1));button(bar,"⟳",()->{scan();draw();});}
void button(LinearLayout bar,String label,Runnable action){TextView b=text(label,15,GOLD);b.setTypeface(Typeface.DEFAULT,Typeface.BOLD);b.setPadding(dp(2),0,dp(2),0);b.setGravity(Gravity.CENTER);b.setBackground(metallic(false));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,dp(48),1);p.setMargins(dp(2),0,dp(2),0);bar.addView(b,p);b.setOnClickListener(v->action.run());}
void reactor(LinearLayout bar){TextView b=text(player!=null&&player.isPlaying()?"Ⅱ":"▶",26,Color.rgb(255,246,213));b.setPadding(0,0,0,0);b.setGravity(Gravity.CENTER);GradientDrawable ring=new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{Color.rgb(22,90,111),Color.rgb(7,30,46),Color.rgb(30,110,137)});ring.setShape(GradientDrawable.OVAL);ring.setStroke(5,GOLD);b.setBackground(ring);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(dp(58),dp(58));p.setMargins(dp(3),0,dp(3),0);bar.addView(b,p);b.setOnClickListener(v->{if(player==null){queue=new ArrayList<>(songs);if(queue.isEmpty()){Toast.makeText(this,"Primero seleccioná tu carpeta de música",Toast.LENGTH_SHORT).show();return;}play(shuffleMode==0?0:new Random().nextInt(queue.size()));}else if(player.isPlaying())player.pause();else player.start();controls();});}
void play(int i){if(queue.isEmpty())return;current=Math.max(0,Math.min(i,queue.size()-1));try{if(player!=null)player.release();player=new MediaPlayer();player.setDataSource(this,queue.get(current).uri);player.setOnPreparedListener(mp->{mp.start();controls();});player.setOnCompletionListener(mp->advance());player.prepareAsync();controls();}catch(Exception e){Toast.makeText(this,"No se pudo reproducir",1).show();}}
void next(int direction){if(queue.isEmpty())queue=new ArrayList<>(songs);if(queue.isEmpty())return;if(shuffleMode==2){queue=new ArrayList<>(songs);play(new Random().nextInt(queue.size()));return;}int i=shuffleMode==1?new Random().nextInt(queue.size()):(current+direction+queue.size())%queue.size();play(i);}
protected void onDestroy(){if(player!=null)player.release();super.onDestroy();}
}